const D = { density: .55, energy: .65, hue: 20, speed: 1, scale: 1, warp: .2, x: .5, y: .46, seed: 0, style: 'lava', act: 'smoulder' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const cl = (v,a,b) => v<a?a:v>b?b:v;
const sty = P.style;
const hz = cl(P.y, .28, .72) * height;
const cx = cl(P.x, .05, .95) * width;
const groundH = Math.max(20, height - hz);
const yOf = t => hz + Math.pow(t, 1.7) * groundH;
const hwOf = t => width * (.045 + t * .95) * .5 * P.scale;
const NR = Math.round(8 + P.density * 20);
const NC = Math.round(6 + P.density * 14);
const H = P.hue;
// thermal false-color ramp: cold->hot along v in 0..1
const thermal = v => { v=cl(v,0,1); const h=(1-v)*230; const s=v<.15?40:90; const b=cl(8+v*92,6,100); return [h,s,b]; };

S.tre = (S.tre||0)*.8 + (A.treble||0)*.2;
S.bass = (S.bass||0)*.8 + (A.bass||0)*.2;
const glow = (.4 + .6*P.energy) * (.55 + .55*K.intensity);
const kick = Math.min(1, K.pulse*(.5+.5*K.intensity) + S.bass*.75);

// real-time scroll + independent vein-pulse phase (never re-phases)
if (S.pt == null || K.t < S.pt) S.pt = K.t;
let dt = K.t - S.pt; S.pt = K.t; dt = cl(dt, 0, .1);
let sp = P.speed * (.4 + .7*K.intensity);
if (P.act === 'eruption') sp *= 1 + 1.3*kick;
if (P.act === 'flowfield') sp *= .35 + 1.0*(.5 + .5*Math.sin(K.t*.04 + K.section*.8));
S.scroll = (S.scroll||0) + dt*sp*.42;
S.vph = (S.vph||0) + dt*(.7+.6*P.speed);   // vein glow breathing time
const scroll = S.scroll, vph = S.vph;
// molten pulse that surges on the beat but always has a slow floor
S.heat = (S.heat||0)*.9 + (.3 + .7*(.5+.5*Math.sin(vph*.9)) + .5*kick)*.1;
const heat = cl(S.heat,0,1);

// ---- cached basalt-plate base (crust tiles; veins drawn live) ----
const key = width+'x'+height+'|'+sty+'|'+Math.round(H)+'|'+P.seed+'|'+Math.round(P.density*8)+'|'+Math.round(P.y*24)+'|'+Math.round(P.scale*8);
if (!S.base || S.key !== key) {
  const g = S.base && S.base.width===width && S.base.height===height ? S.base : createGraphics(width, height);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  const STR = 60;
  // smoke-choked sky
  for (let i=0;i<STR;i++){ const f=i/STR, y=f*hz;
    let h,s,b;
    if (sty==='thermal'){ const c=thermal(.05+.12*(1-f)); h=c[0]; s=c[1]; b=c[2]; }
    else if (sty==='obsidian'){ h=H+200; s=14; b=4+6*(1-f); }
    else { h=H+8; s=40+20*f; b=cl(6+12*(1-f),4,26); }  // lava / ember smoke
    g.fill(h,cl(s,4,90),cl(b,2,80),100); g.rect(0,y,width,hz/STR+1);
  }
  // ground crust plane
  for (let i=0;i<STR;i++){ const t=i/STR, y=yOf(t), y2=yOf((i+1)/STR);
    let h,s,b;
    if (sty==='thermal'){ const c=thermal(.06+.18*(1-t)); h=c[0]; s=c[1]; b=c[2]; }
    else if (sty==='obsidian'){ h=H+210; s=cl(18-8*t,4,30); b=cl(10+6*t,4,22); }
    else { h=H+6; s=30-10*t; b=cl(6+4*t,4,16); }
    g.fill(h,cl(s,3,90),b,100); g.rect(0,y,width,(y2-y)+1);
  }
  // static crust texture: faceted plates
  g.push();
  if (sty==='obsidian'){ // glassy low-poly facets
    for(let ry=0;ry<9;ry++){ const t0=ry/9,t1=(ry+1)/9;
      for(let cc=0;cc<8;cc++){ const u0=cc/8,u1=(cc+1)/8, sh=fr(ry*8+cc);
        const y0=yOf(t0),y1=yOf(t1),hw0=hwOf(t0),hw1=hwOf(t1);
        g.fill(H+205, cl(18-6*t0,4,26), cl(8+26*sh-16*t0,4,50), 34);
        g.quad(cx-hw0+u0*2*hw0,y0, cx-hw0+u1*2*hw0,y0, cx-hw1+u1*2*hw1,y1, cx-hw1+u0*2*hw1,y1); } } }
  else if (sty==='lava'||sty==='thermal'){ // stony grain speckle
    g.blendMode(BLEND);
    for(let i=0;i<180;i++){ const t=.04+.96*fr(i*2), y=yOf(t), hw=hwOf(t);
      const x=cx+(fr(i*2+1)*2-1)*hw; const r=1+t*2.6;
      g.fill(H+6,20,cl(10+30*fr(i*3),6,60),20+30*t); g.ellipse(x,y,r,r); } }
  g.pop();
  S.base = g; S.key = key;
}
image(S.base, 0, 0);

// ---- GLOWING LAVA VEINS between plates (live; the motion floor) ----
push(); blendMode(ADD); noStroke();
for(let r=0;r<NR;r++){ const t0=r/NR,t1=(r+1)/NR; const y0=yOf(t0),y1=yOf(t1);
  const hw0=hwOf(t0),hw1=hwOf(t1);
  for(let c=0;c<NC;c++){ const u0=c/NC,u1=(c+1)/NC; const um=(u0+u1)*.5;
    const vein=Math.abs(Math.sin((um*7+t0*3.1)*2.0)+Math.sin((t0*1.7-um*6)*1.4 + vph*.6));
    const open = vein<0.4 ? (1 - vein/0.4) : 0;   // 0..1 how molten this seam is
    if(open<=0) continue;
    const pulse = .5+.5*Math.sin(vph*1.6 + (r*3+c)*.7);
    const hot = cl(open*(.5+.7*pulse)*(.6+.7*heat),0,1);
    let col;
    if(sty==='thermal'){ col=thermal(.35+.65*hot); }
    else { col=[cl(H+ (1-hot)*20 - 6,0,60), 95, cl(50+55*hot,30,100)]; }
    const x0a=cx-hw0+u0*2*hw0,x0b=cx-hw0+u1*2*hw0,x1a=cx-hw1+u0*2*hw1,x1b=cx-hw1+u1*2*hw1;
    fill(col[0],col[1],col[2], Math.min(60,(14+46*hot)*(.55+.6*glow)));
    quad(x0a,y0,x0b,y0,x1b,y1,x1a,y1); } }
pop();

// ---- crack seams outline (defines the plates) ----
noFill();
for (let r=0; r<=NR; r++){
  let t=(r-(scroll%1))/NR; if(t<=0||t>1)continue;
  const y=yOf(t),hw=hwOf(t), near=t;
  let h,s,b,a,sw;
  if(sty==='obsidian'){ h=H+205; s=16; b=60; a=20+50*near; sw=.6+near*1.6; }
  else if(sty==='thermal'){ const c=thermal(.2); h=c[0]; s=50; b=40; a=16+44*near; sw=.5+near*1.4; }
  else { h=H; s=40; b=cl(16+20*heat,10,60); a=18+48*near; sw=.6+near*1.8; }
  stroke(h,s,b,a*(.5+.6*glow)); strokeWeight(sw);
  beginShape();
  const seg=8;
  for(let k=0;k<=seg;k++){ const u=k/seg, xx=cx-hw+u*2*hw;
    const jj=(fr(r*13+k)*2-1)*hw*.06*(1-t)*4; vertex(xx,y+jj); }
  endShape();
}
// converging plate seams
for (let c=0;c<=NC;c++){ const u=c/NC,d=(u-.5);
  const xTop=cx+d*width*.03*P.scale, xBot=cx+d*width*1.9*P.scale*(1+P.warp*1.2*d*d*4);
  let h,s,b,a;
  if(sty==='obsidian'){ h=H+205; s=14; b=55; a=22; }
  else if(sty==='thermal'){ h=200; s=40; b=45; a=18; }
  else { h=H; s=42; b=cl(20+18*heat,10,60); a=24; }
  stroke(h,s,b,a*(.5+.5*glow)); strokeWeight(.8); line(xTop,hz,xBot,height);
}

// ---- rising embers / sparks (always on) ----
const NP = Math.round(30 + P.density * 90);
push(); blendMode(ADD); noStroke();
for (let i=0;i<NP;i++){
  const lane=fr(i*4);
  let prog=(fr(i*4+2) - vph*.08*(.5+fr(i*4+1)))%1; prog=(prog+1)%1;
  const t=1-prog; if(t<=.02) continue;
  const rise=(1-t)*groundH*.35;
  const y=yOf(t) - rise, hw=hwOf(t);
  const x=cx+(lane*2-1)*hw*.92 + Math.sin(vph*.8+i*1.4)*hw*.1;
  const life=t; const sz=(1+4.5*life)*(1+.5*S.tre);
  let col = sty==='thermal'? thermal(.5+.5*life) : [cl(H+8+ (1-life)*20,0,60), 95, cl(55+45*life,30,100)];
  fill(col[0],col[1],col[2], Math.min(46,(8+34*life)*(.5+.9*glow)));
  ellipse(x,y,sz,sz);
}
pop();

// horizon heat bloom on the beat (partial, safe)
push(); blendMode(ADD); noStroke();
const flare=(kick*.7+K.swell*.3)*glow*(.5+.7*heat);
for(let i=0;i<5;i++){ const rr=(5-i)*groundH*.055*(1+flare);
  let col = sty==='thermal'? thermal(.7) : [H+4,80,98];
  fill(col[0],col[1],col[2], 4+11*flare); rect(0, hz-rr*.45, width, rr); }
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
